SPECIAL_ISBNS = ["42", "", "None", "@", "\\", "/", ",", '"', "'", "héllo世界"]


@override_settings(ROOT_URLCONF="composite_pk.test_admin_probe")
class ProbeTests(TestCase):
    @classmethod
    def setUpTestData(cls):
        cls.tenant_1 = Tenant.objects.create(id=1, name="t1")
        cls.tenant_2 = Tenant.objects.create(id=2, name="t2")
        cls.books = {}
        for isbn in SPECIAL_ISBNS:
            cls.books[isbn] = Book.objects.create(tenant=cls.tenant_1, isbn=isbn)
        cls.book_comma_2 = Book.objects.create(tenant=cls.tenant_2, isbn=",")
        cls.superuser = User.objects.create_superuser("u", "u@e.com", "x")

    def setUp(self):
        self.client.force_login(self.superuser)

    def enc(self, *books):
        return [Book._meta.pk.value_to_string(b.pk) for b in books]

    def test_add_get(self):
        r = self.client.get("/admin/composite_pk/shelf/add/")
        self.assertEqual(r.status_code, 200)

    def test_change_get_selected(self):
        shelf = Shelf.objects.create(name="s")
        shelf.books.add(self.books[""], self.books["@"])
        r = self.client.get(f"/admin/composite_pk/shelf/{shelf.pk}/change/")
        self.assertEqual(r.status_code, 200)
        for value in self.enc(self.books[""], self.books["@"]):
            self.assertIn(value, r.context["adminform"].form.fields["books"].widget.choices.queryset.values_list("pk", flat=True) or [])

    def test_valid_post(self):
        shelf = Shelf.objects.create(name="s")
        r = self.client.post(
            f"/admin/composite_pk/shelf/{shelf.pk}/change/",
            {"name": "s2", "books": self.enc(self.books[""], self.book_comma_2), "tags": []},
        )
        print("POST status:", r.status_code)
        if r.status_code == 200:
            print("ERRORS:", r.context["adminform"].form.errors)
        shelf.refresh_from_db()
        print("name:", shelf.name, "books:", list(shelf.books.values_list("pk", flat=True)))

    def test_invalid_post(self):
        shelf = Shelf.objects.create(name="s")
        shelf.books.add(self.books["42"])
        r = self.client.post(
            f"/admin/composite_pk/shelf/{shelf.pk}/change/",
