        )
        print("INVALID POST status:", r.status_code)
        if r.status_code == 200:
            print("ERRORS:", r.context["adminform"].form.errors)
        shelf.refresh_from_db()
        print("name after fail:", shelf.name, "books:", list(shelf.books.values_list("pk", flat=True)))

