@override_settings(ROOT_URLCONF="composite_pk.test_admin_probe")
class ProbeTests(TestCase):
    @classmethod
    def setUpTestData(cls):
        cls.tenant_1 = Tenant.objects.create(id=1, name="t1")
        cls.tenant_2 = Tenant.objects.create(id=2, name="t2")
        cls.books = {}
        for isbn in SPECIAL_ISBNS:
            cls.books[isbn] = Book.objects.create(tenant=cls.tenant_1, isbn=isbn)
        cls.book_comma_2 = Book.objects.create(tenant=cls.tenant_2, isbn=",")
        cls.superuser = User.objects.create_superuser("u", "u@e.com", "x")

    def setUp(self):
        self.client.raise_request_exception = False
        self.client.force_login(self.superuser)

    def enc(self, *books):
        return [Book._meta.pk.value_to_string(b.pk) for b in books]

    def test_raw_id_get_post(self):
        shelf = Shelf.objects.create(name="s")
        shelf.books.add(self.books[""], self.book_comma_2)
        r = self.client.get(f"/admin/composite_pk/shelf/{shelf.pk}/change/")
        print("RAWID GET status:", r.status_code)
        html = r.content.decode()
        idx = html.find("vManyToManyRawIdAdminField")
        print("widget snippet:", html[idx-400:idx+200].replace("\n", " ")[:600])
        # POST with one encoded key
        enc = self.enc(self.books["@"])[0]
        r = self.client.post(
            f"/admin/composite_pk/shelf/{shelf.pk}/change/",
            {"name": "s", "books": enc},
        )
        print("RAWID POST status:", r.status_code)
        if r.status_code == 200:
            print("ERRORS:", r.context["adminform"].form.errors.as_json())
        shelf.refresh_from_db()
        print("books after:", list(shelf.books.values_list("pk", flat=True)))

    def test_popup_add_value(self):
        self.client.raise_request_exception = True
        r = self.client.post(
            "/admin/composite_pk/book/add/?_popup=1",
            {"tenant": "1", "isbn": "new,isbn", "title": "t", "_popup": "1"},
        )
        print("POPUP status:", r.status_code)
        print("POPUP data:", r.context.get("popup_response_data") if r.context is not None else None)
        if r.context is not None and "adminform" in r.context:
            print("FORM ERRORS:", r.context["adminform"].form.errors.as_json())

    def test_autocomplete_json(self):
        self.client.raise_request_exception = True
        r = self.client.get(
            "/admin/autocomplete/",
            {"app_label": "composite_pk", "model_name": "shelf", "field_name": "books", "term": ""},
        )
        print("AUTOCOMPLETE books status:", r.status_code, r.content[:300])

