            value = tuple(self.rel.model._meta.pk.to_python(value))
        obj = self.rel.model._default_manager.using(self.db).get(**{key: value})
    except (ValueError, TypeError, OverflowError, self.rel.model.DoesNotExist, ValidationError):
        return "", ""

